function curatedRecipe(prepMinutes, cookMinutes, difficulty, amounts, steps, tip) {
  return {
    prepMinutes,
    cookMinutes,
    time: prepMinutes + cookMinutes <= 30 ? "schnell" : prepMinutes + cookMinutes >= 60 ? "aufwendig" : "normal",
    difficulty,
    ingredients: Object.keys(amounts),
    amounts,
    steps: steps.split("|"),
    tip,
    release: "0.2.2"
  };
}

